{% set slugs = ['camera_carlo','ingresso','cucina','soggiorno','camera_laura_livia','bagno_verde','bagno_blu','camera_diego_luisa'] %}
{% set ids = state_attr('sensor.nb_device_active_for_boiler','active_device_ids') %}
{% set count = states('sensor.nb_device_active_for_boiler') | float(none) %}
{% set valid_count = count is not none and count >= 0 and count == (count | int) and ids is sequence and ids is not string and ids is not mapping and count == (ids | unique | list | count) %}
{% set ns = namespace(rooms=[], valves=[]) %}
{% set now_s = as_timestamp(now()) %}
{% for slug in slugs %}
  {% set room = 'climate.trv_vtherm_' ~ slug %}
  {% set a = states[room].attributes if has_value(room) else {} %}
  {% set specific = a.get('specific_states') or {} %}
  {% set config = a.get('configuration') or {} %}
  {% set over = a.get('vtherm_over_climate') or {} %}
  {% set window = a.get('window_manager') or {} %}
  {% set sensor = window.get('window_sensor_entity_id') %}
  {% set bypass = window.get('is_window_bypass') == true %}
  {% set closed = bypass or (window.get('window_state') == 'off' and sensor is string and is_state(sensor,'off')) %}
  {% set current = a.get('current_temperature') | float(none) %}
  {% set target = a.get('temperature') | float(none) %}
  {% set age = now_s - as_timestamp(specific.get('last_temperature_datetime'),0) %}
  {% set split = slug in ['camera_carlo','camera_diego_luisa'] %}
  {% set split_id = 'climate.camera_carlo_condizionatore' if slug == 'camera_carlo' else 'climate.camera_diego_luisa_condizionatore_aria_stanza' %}
  {% set radiator_allowed = not split or (is_state('input_boolean.' ~ slug ~ '_pdc_in_gestione','off') and is_state(split_id,'off')) %}
  {% if valid_count and is_state(room,['heat','auto']) and a.get('is_ready') == true and specific.get('is_initialized') == true
        and config.get('is_used_by_central_boiler') == true and closed and radiator_allowed
        and (specific.get('inhibition') or {}).get('inhibited',false) == false
        and (a.get('safety_manager') or {}).get('safety_state','off') == 'off'
        and (a.get('power_manager') or {}).get('overpowering_state','off') == 'off'
        and over.get('avatto_room_demand') != false
        and current is not none and target is not none and 0 <= age <= 3600 %}
    {% set physical = namespace(active=[]) %}
    {% for valve in over.get('underlying_entities',[]) %}
      {% if valve in ids and is_state(valve,['heat','auto']) and state_attr(valve,'hvac_action') == 'heating' %}
        {% set physical.active = physical.active + [valve] %}
      {% endif %}
    {% endfor %}
    {% if physical.active %}
      {% set gap = (target-current) | round(3) %}
      {% set pilot_ok = slug not in ['camera_carlo','bagno_blu'] or over.get('avatto_room_demand') == true %}
      {% set ns.rooms = ns.rooms + [{'slug':slug,'target':target,'gap':gap,'pilot_ok':pilot_ok}] %}
      {% set ns.valves = ns.valves + physical.active %}
    {% endif %}
  {% endif %}
{% endfor %}
{{ {'ok':valid_count and is_state('select.central_mode',['Auto','Heat only']),
    'master':states('climate.termostato_ingresso'),'count':ns.valves | unique | list | count,'rooms':ns.rooms,
    'manual':states('binary_sensor.caldaia_richiesta_manuale_oikos'),
    'pilot':states('input_boolean.caldaia_filtro_pilota_avatto'),
    'pilot_ready':is_state('binary_sensor.caldaia_avvio_automatico_avatto','on'),
    'consent':is_state('input_boolean.richiesta_caldaia_vtherm','on') and is_state('binary_sensor.central_boiler','on')} }}

