{% set n = now_ts | float %}
{% set c = cycle if cycle is mapping else {} %}
{% set mode = raw.master %}
{% set saved = c.get('m') %}
{% set stopped = c.get('off') | float(none) %}
{% if mode == 'off' and (saved != 'off' or stopped is none or stopped < 0 or stopped > n) %}{% set stopped = n %}{% endif %}
{% set usable = raw.ok and raw.count > 0 and mode in ['off','heat'] %}
{% set qualified = raw.rooms | selectattr('gap','ge',0.3) | list %}
{% set pilot_rooms = qualified | selectattr('pilot_ok') | list %}
{% set automatic_ok = raw.pilot in ['on','off'] and (raw.pilot == 'off' or raw.get('pilot_ready',false)) %}
{% set normal = usable and raw.count >= 2 and qualified | count > 0 and automatic_ok %}
{% set ready = c.get('r') | float(none) if normal else none %}
{% if normal and (ready is none or ready < 0 or ready > n) %}{% set ready = n %}{% endif %}
{% set one = qualified[0] if usable and raw.count == 1 and qualified | count == 1 and automatic_ok and (raw.pilot == 'off' or qualified[0].pilot_ok) else none %}
{% set prior = c.get('s',[]) %}
{% set same = one is not none and prior is sequence and prior is not string and prior | length == 3 and prior[0] == one.slug and prior[1] == one.target %}
{% set single_since = prior[2] | float(none) if same else none %}
{% if one is not none and (single_since is none or single_since < 0 or single_since > n) %}{% set single_since = n %}{% endif %}
{% set single = [one.slug,one.target,single_since | int] if one is not none else [] %}
{% set ns = namespace(action='none',reason='no_demand',deadline=none) %}
{% if mode == 'heat' %}
  {% set ns.reason = 'maintain' %}
  {% if not usable %}{% set ns.action = 'off' %}{% set ns.reason = 'no_valid_radiator' %}{% endif %}
{% elif mode == 'off' %}
  {% if usable and raw.manual == 'on' %}
    {% set ns.action = 'heat' %}{% set ns.reason = 'manual' %}
  {% elif usable and raw.manual == 'off' and automatic_ok and stopped is not none %}
    {% set cooldown = stopped + 600 %}
    {% if normal %}
      {% set ns.deadline = [ready + 120,cooldown] | max %}
      {% set ns.reason = 'normal_wait' %}
      {% if n >= ns.deadline and raw.consent %}{% set ns.action = 'heat' %}{% set ns.reason = 'normal' %}{% elif n >= ns.deadline %}{% set ns.deadline = none %}{% set ns.reason = 'awaiting_consent' %}{% endif %}
    {% elif one is not none %}
      {% set ns.deadline = [single_since + 900,cooldown] | max %}
      {% set ns.reason = 'single_wait' %}
      {% if n >= ns.deadline %}{% set ns.action = 'heat' %}{% set ns.reason = 'single' %}{% endif %}
    {% else %}{% set ns.reason = 'thermal_wait' %}
    {% endif %}
  {% elif not raw.ok %}{% set ns.reason = 'data_or_central' %}
  {% elif usable %}{% set ns.reason = 'data_missing' %}
  {% endif %}
{% else %}{% set ns.reason = 'master_unavailable' %}
{% endif %}
{{ {'action':ns.action,'reason':ns.reason,'deadline':ns.deadline,
    'cycle':{'m':mode if mode in ['off','heat'] else saved,'off':stopped | int if stopped is not none else none,
             'r':ready | int if ready is not none else none,'s':single}} }}

